def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate the solid barrier and determine the direction of gravity.
    barrier = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                barrier = (r, c)
                break
        if barrier is not None:
            break

    br, bc = barrier
    if all(grid[br][c] == 2 for c in range(w)):
        dr, dc = (1, 0) if br == 0 else (-1, 0)
    else:
        dr, dc = (0, 1) if bc == 0 else (0, -1)

    # Find connected same-color objects, excluding the barrier.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color == 2 or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            stack = [(r, c)]
            while stack:
                x, y = stack.pop()
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and
                            (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        cells.add((nx, ny))
