            objects.append((color, cells))

    # Settle objects closest to the barrier first.
    if dr == 1:
        objects.sort(key=lambda obj: max(r for r, c in obj[1]), reverse=True)
    elif dr == -1:
        objects.sort(key=lambda obj: min(r for r, c in obj[1]))
    elif dc == 1:
        objects.sort(key=lambda obj: max(c for r, c in obj[1]), reverse=True)
    else:
        objects.sort(key=lambda obj: min(c for r, c in obj[1]))

    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                out[r][c] = 2

    for color, cells in objects:
